type ImportStatus = 'published' | 'needs_review';
type ImportAnswerType = 'short_answer' | 'multi_part' | 'essay';

interface ImportSolutionStep {
  title: string;
  explanation: string;
}

interface ImportPassage {
  slug: string;
  title: string | null;
  bodyMd: string;
  sourceAuthor: string | null;
  sourceNote: string | null;
}

interface ImportTask {
  taskNumber: number;
  topicSlug: string;
  topicName: string;
  passageSlug: string | null;
  sourcePage: number;
  rawStatement: string;
  conditionMd: string;
  answerType?: ImportAnswerType;
  correctAnswer: string;
  /** Only for `answerType: 'essay'` — a genuine, authored example essay grounded in this task's own passage. */
  sampleEssayMd?: string;
  /**
   * True ONLY for a `short_answer` task whose own wording ("Запишите
   * номера ответов" / "Укажите цифру(-ы), на месте которой(-ых)…")
   * is the standard EGE multi-select format, where the official
   * convention accepts the selected digits in any order — never set
   * for a task whose digits encode something order-dependent. See
   * `digitSetOrderInsensitive` on `schema.tasks` for the full
   * rationale; defaults to false (unset) for every other task.
   */
  digitSetOrderInsensitive?: boolean;
  correctAnswerDisplay?: string;
  explanationMd: string;
  hintMd: string;
  solutionSteps: readonly ImportSolutionStep[];
  status: ImportStatus;
}

